package ch.bbw.zork;import java.io.BufferedReader;import java.io.InputStream;import java.io.InputStreamReader;/** * Liest die Eingaben des Spielers ein und wandelt * sie in Befehle für das Zork-Spiel um. */public class Parser {	private CommandWords validCommandWords;	private InputStream inputStream;	/**	 * Erstellt einen neuen Parser.	 *	 * @param inputStream Eingabequelle für die Befehle	 */	public Parser(InputStream inputStream) {		this.inputStream = inputStream;		this.validCommandWords = new CommandWords();	}	/**	 * Liest die Eingabe des Spielers und erstellt daraus einen Befehl.	 *	 * @return eingegebener Befehl	 */	public Command getCommand() {		String inputLine;		System.out.print("> ");		BufferedReader bufferedReader =				new BufferedReader(new InputStreamReader(this.inputStream));		try {			inputLine = bufferedReader.readLine();			String[] tokens = inputLine.split(" ");			switch (tokens.length) {				case 2:					if (validCommandWords.isCommand(tokens[0])) {						return new Command(tokens[0], tokens[1]);					} else {						return new Command(null, tokens[1]);					}				case 1:					if (validCommandWords.isCommand(tokens[0])) {						return new Command(tokens[0]);					} else {						return new Command(null);					}				default:					break;			}		} catch (java.io.IOException exc) {			System.out.println(					"There was an error during reading: " + exc.getMessage());		}		return new Command(null);	}	/**	 * Gibt alle verfügbaren Befehle zurück.	 *	 * @return alle gültigen Befehle	 */	public String showCommands() {		return validCommandWords.showAll();	}}